#!/usr/bin/env node
// constat:template id=parts-merge-report version=75 sha256=8d537b274828bb290e2efd145fdda5d3f01f1871c0b716a7cf02f55c68e660fa
// Generated by DoneMark. Merges the check reports of this repository's parts (its apps one folder
// down) into the one report DoneMark reads.
//
// Usage: constat-merge-parts.mjs <out> <folder>=<that part's checks.json> ... [--allow-none]
import { existsSync, mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import { dirname } from 'node:path';

const args = process.argv.slice(2);
const allowNone = args.includes('--allow-none');
const [out, ...pairs] = args.filter((a) => a !== '--allow-none');
if (!out || pairs.length === 0) {
  console.error('usage: constat-merge-parts.mjs <out> <folder>=<checks.json> ... [--allow-none]');
  process.exit(2);
}

const merged = { schema: 'constat.check-report/v1', checks: [], notes: [] };
const folderOf = [];
let read = 0;
for (const pair of pairs) {
  const at = pair.indexOf('=');
  const folder = pair.slice(0, at);
  const path = pair.slice(at + 1);
  if (!existsSync(path)) {
    merged.notes.push({ package: folder, kind: 'no-report', sentence: folder + '/ published no report: its tests did not run, or did not finish.' });
    continue;
  }
  const body = JSON.parse(readFileSync(path, 'utf8'));
  read += 1;
  for (const check of Array.isArray(body.checks) ? body.checks : []) {
    const file = typeof check.file === 'string' && check.file !== '' ? folder + '/' + check.file : (check.file ?? null);
    merged.checks.push({ ...check, file });
    folderOf.push(folder);
  }
  for (const note of Array.isArray(body.notes) ? body.notes : []) merged.notes.push({ ...note, package: note.package || folder });
}

const count = new Map();
for (const check of merged.checks) count.set(check.name, (count.get(check.name) ?? 0) + 1);
merged.checks.forEach((check, i) => {
  if (count.get(check.name) > 1) check.name = folderOf[i] + ' > ' + check.name;
});
if (merged.notes.length === 0) delete merged.notes;

if (read === 0) {
  console.error('no part published a report');
  process.exit(allowNone ? 0 : 1);
}
mkdirSync(dirname(out), { recursive: true });
writeFileSync(out, JSON.stringify(merged, null, 2) + '\n');
console.log('merged ' + merged.checks.length + ' checks from ' + read + ' of ' + pairs.length + ' parts');
